using System.ComponentModel.DataAnnotations;
using SquadSync.Api.People;

namespace SquadSync.Api.Rosters;

/// <summary>Supply exactly one of PersonId or NewPerson. Identifiers are generated by Application.</summary>
public sealed class AddPlayerRequest : IValidatableObject
{
    public Guid? PersonId { get; init; }
    public CreatePersonRequest? NewPerson { get; init; }

    public string? JerseyNumber { get; init; }

    [Required]
    [RegularExpression("^(Active|Reserved|Suspended)$")]
    public string? RosterStatus { get; init; }

    public IEnumerable<ValidationResult> Validate(ValidationContext validationContext)
    {
        if (PersonId.HasValue == (NewPerson is not null))
            yield return new ValidationResult("Supply exactly one of personId or newPerson.", ["personId", "newPerson"]);
    }
}
